package cn.zhuatech.ehs.controller; import cn.zhuatech.ehs.common.ApiResponse; import cn.zhuatech.ehs.dto.EhsDto.*; import cn.zhuatech.ehs.service.EhsService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('EHS_MANAGER','QUALITY','ADMIN')") public class EhsAdminController {private final EhsService service;public EhsAdminController(EhsService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<SafetyInspectionView>> orders(){return ApiResponse.ok(service.safetyInspections());}}
